<template><BtgPageContainer as="section" width="application" aria-labelledby="translation-title"><div v-if="state==='loading'" role="status"><h1 id="translation-title">Loading translation</h1></div><div v-else-if="state==='error'" role="alert"><h1 id="translation-title">Translation unavailable</h1><BtgButton @click="load">Try again</BtgButton></div><template v-else><RouterLink :to="`/authoring/courses/${workspace.source.courseId}/versions/${workspace.source.version}/translations`">Back to translations</RouterLink><header><p>Translation workspace</p><h1 id="translation-title">{{ workspace.course.title.source }} → {{ workspace.targetLanguage }}</h1><p>Source version {{ workspace.source.version }} · {{ workspace.source.language }} · {{ workspace.completeness.translatedFields }} of {{ workspace.completeness.totalTranslatableFields }} fields translated.</p></header><p v-if="notice" role="status">{{notice}}</p><div v-if="conflict" role="alert"><p>This translation changed elsewhere. Your unsaved edits are still on this page.</p><BtgButton variant="secondary" @click="load">Reload latest translation</BtgButton></div><section><h2>Course metadata</h2><TranslationField label="Course title" :field="workspace.course.title" @change="change({target:'COURSE',field:'title'},$event)"/><TranslationField label="Course description" :field="workspace.course.description" multiline @change="change({target:'COURSE',field:'description'},$event)"/><BtgButton :disabled="!changes.length||saving" @click="save">{{saving?'Saving…':'Save course metadata'}}</BtgButton></section><section v-for="module in workspace.modules" :key="module.sourceStableKey"><h2>{{module.title.source}} — {{module.completeness.translatedFields}} of {{module.completeness.totalTranslatableFields}}</h2><TranslationField label="Module title" :field="module.title" @change="change({target:'MODULE',moduleKey:module.sourceStableKey,field:'title'},$event)"/><section v-for="lesson in module.lessons" :key="lesson.sourceStableKey"><h3>{{lesson.title.source}} — {{lesson.completeness.translatedFields}} of {{lesson.completeness.totalTranslatableFields}}</h3><TranslationField label="Lesson title" :field="lesson.title" @change="change({target:'LESSON',moduleKey:module.sourceStableKey,lessonKey:lesson.sourceStableKey,field:'title'},$event)"/><TranslationField label="Lesson description" :field="lesson.description" multiline @change="change({target:'LESSON',moduleKey:module.sourceStableKey,lessonKey:lesson.sourceStableKey,field:'description'},$event)"/><div v-for="block in lesson.blocks" :key="block.sourceBlockKey"><h4>{{block.type}}</h4><pre v-if="block.type==='CODE'">{{block.code}}</pre><p v-if="block.type==='KNOWLEDGE_CHECK'">Assessment reference: {{block.assessmentKey}}</p><TranslationField v-for="(field,name) in block.fields" :key="name" :label="`${block.type} ${name}`" :field="field" multiline @change="change({target:'BLOCK',moduleKey:module.sourceStableKey,lessonKey:lesson.sourceStableKey,blockKey:block.sourceBlockKey,field:name},$event)"/></div><BtgButton :disabled="!changes.length||saving" @click="save">Save lesson changes</BtgButton></section></section><section><h2>Assessments</h2><div v-for="assessment in workspace.assessments" :key="assessment.assessmentKey"><h3>Assessment</h3><div v-for="question in assessment.questions" :key="question.sourceStableKey"><TranslationField label="Question prompt" :field="question.prompt" multiline @change="change({target:'ASSESSMENT_QUESTION',assessmentKey:assessment.assessmentKey,questionKey:question.sourceStableKey,field:'prompt'},$event)"/><TranslationField v-for="option in question.options" :key="option.sourceStableKey" label="Option label" :field="option.text" @change="change({target:'ASSESSMENT_OPTION',assessmentKey:assessment.assessmentKey,questionKey:question.sourceStableKey,itemKey:option.sourceStableKey,field:'text'},$event)"/></div></div></section><section><h2>Publication</h2><p v-if="!workspace.completeness.complete">Complete all translatable fields before publishing.</p><BtgButton :disabled="!workspace.completeness.complete||publishing" @click="publish">{{publishing?'Publishing…':`Publish ${workspace.targetLanguage} translation of ${workspace.source.version}`}}</BtgButton></section></template></BtgPageContainer></template>
<script setup lang="ts">import{ref,watch}from'vue';import{useRoute}from'vue-router';import{APIProblemError}from'../api/client';import BtgButton from'../components/BtgButton.vue';import BtgPageContainer from'../components/BtgPageContainer.vue';import TranslationField from'../components/TranslationField.vue';import{getTranslation,patchTranslation,publishTranslation,type TranslationChange,type TranslationWorkspace}from'../translations/translations';const route=useRoute(),workspace=ref<TranslationWorkspace>({}as TranslationWorkspace),state=ref<'loading'|'ready'|'error'>('loading'),changes=ref<TranslationChange[]>([]),saving=ref(false),publishing=ref(false),conflict=ref(false),notice=ref('');let generation=0;watch(()=>route.params.translationId,load,{immediate:true});async function load(){const id=String(route.params.translationId||''),n=++generation;state.value='loading';try{workspace.value=await getTranslation(id);if(n===generation){changes.value=[];conflict.value=false;state.value='ready'}}catch{if(n===generation)state.value='error'}}function change(target:Record<string,unknown>,translated:string|null){const key=JSON.stringify(target);changes.value=[...changes.value.filter(c=>JSON.stringify(Object.fromEntries(Object.entries(c).filter(([k])=>k!=='translated')))!==key),{...target,translated} as TranslationChange]}async function save(){if(!changes.value.length||saving.value)return;saving.value=true;notice.value='';try{await patchTranslation(workspace.value.translationId,workspace.value.revision,changes.value);await load();notice.value='Translation saved.'}catch(error){if(error instanceof APIProblemError&&error.problem&&'code'in error.problem&&error.problem.code==='translation_revision_conflict')conflict.value=true;else notice.value='We could not save your edits. They are still here.'}finally{saving.value=false}}async function publish(){if(!workspace.value.completeness.complete||!confirm(`Publish this translation of source version ${workspace.value.source.version}?`))return;publishing.value=true;try{await publishTranslation(workspace.value.translationId,workspace.value.revision);notice.value='Translation published.';await load()}catch(error){notice.value=error instanceof APIProblemError?'Publication could not be completed.':'Translation publication is unavailable.'}finally{publishing.value=false}}</script>
